const takeDealUnits = `-- name: TakeDealUnits :one
UPDATE launches SET deal_remaining = deal_remaining - $1::int
WHERE id = $2 AND status = 'LIVE' AND deal_remaining >= $1::int RETURNING deal_remaining
`

type TakeDealUnitsParams struct {
	Qty int32     `json:"qty"`
	ID  uuid.UUID `json:"id"`
}

// The source of truth for deal units (LLD 8.4): no row means sold out.
func (q *Queries) TakeDealUnits(ctx context.Context, arg TakeDealUnitsParams) (int32, error) {
	row := q.db.QueryRow(ctx, takeDealUnits, arg.Qty, arg.ID)
	var deal_remaining int32
	err := row.Scan(&deal_remaining)
	return deal_remaining, err
}

